// ---------------------------------------------------------------------------
// Generate a paste-ready SQL seed (a single PL/pgSQL DO block) from the static
// menu in src/lib/menu-data.ts. Run once; it threads new row IDs via variables
// so categories -> dishes -> variants -> modifier groups/options link correctly.
//
//   node scripts/generate-seed-sql.mjs   (writes supabase/migrations/0003_seed_menu.sql)
//
// The generated file starts by clearing the menu, so it is safe to re-run.
// ---------------------------------------------------------------------------

import { writeFileSync } from "node:fs";
import { menu } from "../src/lib/menu-data.ts";

const str = (v) => (v == null ? "null" : `'${String(v).replace(/'/g, "''")}'`);
const numOrNull = (v) => (v == null ? "null" : String(v));
const bool = (v) => (v ? "true" : "false");
const arr = (tags) => (tags && tags.length ? `'{${tags.join(",")}}'` : `'{}'`);

const lines = [];
lines.push("-- Auto-generated by scripts/generate-seed-sql.mjs — do not edit by hand.");
lines.push("-- Loads the baseline menu. Safe to re-run (clears the menu first).");
lines.push("do $$");
lines.push("declare cat_id uuid; dish_id uuid; grp_id uuid;");
lines.push("begin");
lines.push("  delete from public.menu_categories;"); // cascades to all children

menu.forEach((category, ci) => {
  lines.push("");
  lines.push(`  -- ${category.title}`);
  lines.push(
    `  insert into public.menu_categories (slug, title, blurb, sort_order)` +
      ` values (${str(category.slug)}, ${str(category.title)}, ${str(category.blurb)}, ${ci})` +
      ` returning id into cat_id;`
  );

  category.dishes.forEach((dish, di) => {
    lines.push(
      `  insert into public.dishes (category_id, name, description, base_price, dietary, orderable, available, sort_order)` +
        ` values (cat_id, ${str(dish.name)}, ${str(dish.description ?? null)}, ${numOrNull(dish.basePrice)}, ${arr(dish.dietary)}, ${bool(dish.orderable ?? true)}, true, ${di})` +
        ` returning id into dish_id;`
    );

    if (dish.variants?.length) {
      const values = dish.variants
        .map((v, i) => `(dish_id, ${str(v.label)}, ${numOrNull(v.price)}, ${i})`)
        .join(", ");
      lines.push(
        `  insert into public.dish_variants (dish_id, label, price, sort_order) values ${values};`
      );
    }

    dish.modifiers?.forEach((group, gi) => {
      lines.push(
        `  insert into public.modifier_groups (dish_id, label, type, required, min_select, max_select, sort_order)` +
          ` values (dish_id, ${str(group.label)}, ${str(group.type)}, ${bool(group.required ?? false)}, ${numOrNull(group.min)}, ${numOrNull(group.max)}, ${gi})` +
          ` returning id into grp_id;`
      );
      if (group.options.length) {
        const values = group.options
          .map((o, i) => `(grp_id, ${str(o.label)}, ${numOrNull(o.priceDelta)}, ${i})`)
          .join(", ");
        lines.push(
          `  insert into public.modifier_options (group_id, label, price_delta, sort_order) values ${values};`
        );
      }
    });
  });
});

lines.push("end $$;");
lines.push("");

const out = "supabase/migrations/0003_seed_menu.sql";
writeFileSync(out, lines.join("\n"));
console.log(`Wrote ${out} (${lines.length} lines)`);
